    open_count = 0
    while i < len(paren_string) and open_count != 0:
        if paren_string[i] == "(":
            open_count += 1
        elif paren_string[i] == ")":
            open_count -= 1
        i += 1

    if open_count == 0:
        result.append(paren_string[:i])
    else:
        result.extend(separate_paren_groups_helper(paren_string[i + 1:], i))

    return result

