def check_if_prime(number: int) -> bool:
    if number > 1:
        if number == 2:
            return True
        if number % 2 == 0:
            return False
        i = 3
        while i < int(number ** 0.5 + 1):
            if number % i == 0:
                return False
            i += 2
        return True
    return False

def find_largest_prime_number(max_num: int) -> int:
    for number in range(max_num, 1, -1):
        if check_if_prime(number):
            return number
    return 0

