def standard_deviation(numbers: List[float]) -> float:
    """ Calculate standard deviation of given numbers. Standard deviation is
    defined as:
    std = sqrt(Sum ((x - x_mean) ** 2) / N)
    >>> standard_deviation([1, 2, 3, 4, 5])
    1.58
    """
    average = mean(numbers)
    squared_differences = [(x - average) ** 2 for x in numbers]
    sum_of_squared_differences = sum(squared_differences)
    return sum_of_squared_differences ** 0.5


