def count_max_bracket_depth(brackets_str: str) -> int:
    """ Return the max depth of parentheses for any valid sequence.
    E.g. ((((())))()) has max depth of 5.

    >>> count_max_bracket_depth('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
