def remove_duplicates(strings: List[str]) -> List[str]:
    """ Remove duplicates from an input list of strings
    >>> remove_duplicates(['a', 'b', 'c', 'c', 'd', 'e', 'f', 'f'])
    ['a', 'b', 'c', 'd', 'e', 'f']
    """
    unique_list = []
    for string in strings:
        if string not in unique_list:
            unique_list.append(string)
    return unique_list


